    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        uint cBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;
        bool reverted;
        c.sendMoney(address(this), amount, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint cBalanceAfter = address(c).balance;
        uint selfBalanceAfter = address(this).balance;
        assert(cBalanceAfter + selfBalanceAfter == cBalanceBefore + selfBalanceBefore);
    }

    receive() external payable {}
}

