// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount, bytes memory data) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint cBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;
        bool reverted;
        try c.sendMoney(address(this), amount, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint cBalanceAfter = address(c).balance;
        uint selfBalanceAfter = address(this).balance;
        assertTrue(cBalanceAfter + selfBalanceAfter == cBalanceBefore + selfBalanceBefore);
    }

    function testFuzz_run(uint256 amount, bytes memory data) public {
        _run(amount, data);
    }

    receive() external payable {}
}
